\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme: Academic Navy / Gold / Teal ──
\definecolor{primary}{HTML}{0C2340}
\definecolor{secondary}{HTML}{B8860B}
\definecolor{accent}{HTML}{0D7377}
\definecolor{bgposter}{HTML}{F0F2F5}
\definecolor{textdark}{HTML}{1A1A2E}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8EDF5}
\definecolor{goldlight}{HTML}{FDF8EE}
\definecolor{teallight}{HTML}{EBF5F5}
\definecolor{navylight}{HTML}{E8EDF5}
\definecolor{goldtitlebg}{HTML}{F5EEDB}
\definecolor{tealtitlebg}{HTML}{D6ECEC}
\definecolor{navytitlebg}{HTML}{D4DCE8}
\definecolor{tableheader}{HTML}{0C2340}
\definecolor{tablerow1}{HTML}{F0F2F5}
\definecolor{tablerow2}{HTML}{FFFFFF}
\definecolor{golddark}{HTML}{9A6E00}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldlight,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=goldtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=teallight,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=tealtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navylight,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{84}{100}\selectfont\bfseries QS World University Rankings 2026}\\[16pt]
  {\fontsize{40}{48}\selectfont Top Global Universities Compared}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{white!70} A data-driven comparison of the world's leading universities}
}

% ══════════════════════════════════════════════════════════
% STATS BANNER
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{secondary!50},
  borderline north={3pt}{0pt}{primary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 1,500+}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Universities Ranked}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 105}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Countries}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{secondary!40}{goldlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{secondary} 100}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textdark} MIT's Perfect Score}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 27}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textdark} US in Top 100}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{primary!30}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 17}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textdark} UK in Top 100}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% TOP 10 TABLE — CENTERPIECE (span 2 columns, large)
% ══════════════════════════════════════════════════════════
\posterbox[navycard, title={Top 10 Universities Worldwide}
]{name=top10, column=1, span=2, between=row6 and row15}{
  \fontsize{32}{42}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{@{\hspace{8pt}}c @{\hspace{16pt}} p{0.48\linewidth} @{\hspace{12pt}} p{0.18\linewidth} @{\hspace{12pt}} c @{\hspace{8pt}}}
    \rowcolor{primary}
    {\color{white}\fontsize{34}{42}\selectfont\bfseries Rank} &
    {\color{white}\fontsize{34}{42}\selectfont\bfseries University} &
    {\color{white}\fontsize{34}{42}\selectfont\bfseries Country} &
    {\color{white}\fontsize{34}{42}\selectfont\bfseries Score} \\
    \rowcolor{secondary!15}
    {\fontsize{38}{46}\selectfont\bfseries\color{secondary} 1} &
    {\fontsize{34}{42}\selectfont\bfseries Massachusetts Institute of Technology (MIT)} &
    {\fontsize{30}{38}\selectfont United States} &
    {\fontsize{40}{48}\selectfont\bfseries\color{secondary} 100} \\
    \rowcolor{white}
    {\fontsize{34}{42}\selectfont\bfseries 2} &
    {\fontsize{32}{40}\selectfont Imperial College London} &
    {\fontsize{30}{38}\selectfont United Kingdom} &
    {\fontsize{34}{42}\selectfont\bfseries 98.5} \\
    \rowcolor{primary!8}
    {\fontsize{34}{42}\selectfont\bfseries 3} &
    {\fontsize{32}{40}\selectfont University of Oxford} &
    {\fontsize{30}{38}\selectfont United Kingdom} &
    {\fontsize{34}{42}\selectfont\bfseries 97.9} \\
    \rowcolor{white}
    {\fontsize{34}{42}\selectfont\bfseries 4} &
    {\fontsize{32}{40}\selectfont Harvard University} &
    {\fontsize{30}{38}\selectfont United States} &
    {\fontsize{34}{42}\selectfont\bfseries 97.6} \\
    \rowcolor{primary!8}
    {\fontsize{34}{42}\selectfont\bfseries 5} &
    {\fontsize{32}{40}\selectfont University of Cambridge} &
    {\fontsize{30}{38}\selectfont United Kingdom} &
    {\fontsize{34}{42}\selectfont\bfseries 97.0} \\
    \rowcolor{white}
    {\fontsize{34}{42}\selectfont\bfseries 6} &
    {\fontsize{32}{40}\selectfont Stanford University} &
    {\fontsize{30}{38}\selectfont United States} &
    {\fontsize{34}{42}\selectfont\bfseries 96.8} \\
    \rowcolor{primary!8}
    {\fontsize{34}{42}\selectfont\bfseries 7} &
    {\fontsize{32}{40}\selectfont ETH Zurich} &
    {\fontsize{30}{38}\selectfont Switzerland} &
    {\fontsize{34}{42}\selectfont\bfseries 95.3} \\
    \rowcolor{white}
    {\fontsize{34}{42}\selectfont\bfseries 8} &
    {\fontsize{32}{40}\selectfont National University of Singapore (NUS)} &
    {\fontsize{30}{38}\selectfont Singapore} &
    {\fontsize{34}{42}\selectfont\bfseries 94.7} \\
    \rowcolor{primary!8}
    {\fontsize{34}{42}\selectfont\bfseries 9} &
    {\fontsize{32}{40}\selectfont UCL (University College London)} &
    {\fontsize{30}{38}\selectfont United Kingdom} &
    {\fontsize{34}{42}\selectfont\bfseries 94.2} \\
    \rowcolor{white}
    {\fontsize{34}{42}\selectfont\bfseries 10} &
    {\fontsize{32}{40}\selectfont California Institute of Technology (Caltech)} &
    {\fontsize{30}{38}\selectfont United States} &
    {\fontsize{34}{42}\selectfont\bfseries 93.8} \\
  \end{tabular}
  \vspace{8pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\centering\vspace{6pt}
    {\fontsize{30}{38}\selectfont\color{textdark} MIT holds the \#1 position for a record-extending streak, demonstrating sustained dominance in research, employer reputation, and academic prestige.}
  \vspace{6pt}}}
}

% ══════════════════════════════════════════════════════════
% METHODOLOGY — right column, upper
% ══════════════════════════════════════════════════════════
\posterbox[goldcard, title={How Are Universities Ranked?}
]{name=methodology, column=3, span=1, between=row6 and row15}{
  \fontsize{32}{42}\selectfont
  {\fontsize{30}{38}\selectfont\color{textgray} QS evaluates six core indicators:}

  \vspace{12pt}

  \colorbox{secondary!22}{\parbox{0.94\linewidth}{\vspace{8pt}\centering
    {\fontsize{48}{58}\selectfont\bfseries\color{secondary} 40\%}\\[4pt]
    {\fontsize{30}{38}\selectfont\bfseries Academic Reputation}\\[2pt]
    {\fontsize{26}{32}\selectfont\color{textgray} Survey of 130,000+ academics}
  \vspace{8pt}}}

  \vspace{10pt}

  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!18}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{42}{50}\selectfont\bfseries\color{primary} 20\%}\\[3pt]
      {\fontsize{26}{32}\selectfont\bfseries Faculty/Student}\\
      {\fontsize{26}{32}\selectfont\bfseries Ratio}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Teaching capacity}
    \vspace{6pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!18}{\parbox{0.92\linewidth}{\vspace{6pt}\centering
      {\fontsize{42}{50}\selectfont\bfseries\color{accent} 20\%}\\[3pt]
      {\fontsize{26}{32}\selectfont\bfseries Citations per}\\
      {\fontsize{26}{32}\selectfont\bfseries Faculty}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Research impact}
    \vspace{6pt}}}
  \end{minipage}

  \vspace{10pt}

  \colorbox{secondary!15}{\parbox{0.94\linewidth}{\vspace{6pt}\centering
    {\fontsize{38}{46}\selectfont\bfseries\color{secondary} 10\%}
    {\fontsize{28}{34}\selectfont\bfseries\quad Employer Reputation}
  \vspace{6pt}}}

  \vspace{8pt}

  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!12}{\parbox{0.92\linewidth}{\vspace{5pt}\centering
      {\fontsize{34}{42}\selectfont\bfseries\color{primary} 5\%}\\[2pt]
      {\fontsize{24}{30}\selectfont Int'l Faculty}
    \vspace{5pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!12}{\parbox{0.92\linewidth}{\vspace{5pt}\centering
      {\fontsize{34}{42}\selectfont\bfseries\color{accent} 5\%}\\[2pt]
      {\fontsize{24}{30}\selectfont Int'l Students}
    \vspace{5pt}}}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% REGIONAL REPRESENTATION — bottom left, span 1
% ══════════════════════════════════════════════════════════
\posterbox[tealcard, title={Regional Representation in Top 100}
]{name=regional, column=1, span=1, between=row15 and row20}{
  \fontsize{30}{40}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{\hspace{6pt}} p{0.58\linewidth} @{\hspace{8pt}} c @{\hspace{6pt}}}
    \rowcolor{accent}
    {\color{white}\fontsize{30}{38}\selectfont\bfseries Region} &
    {\color{white}\fontsize{30}{38}\selectfont\bfseries Count} \\
    \rowcolor{accent!12}
    {\fontsize{30}{38}\selectfont Europe} &
    {\fontsize{34}{42}\selectfont\bfseries 38} \\
    \rowcolor{white}
    {\fontsize{30}{38}\selectfont North America} &
    {\fontsize{34}{42}\selectfont\bfseries 30} \\
    \rowcolor{accent!12}
    {\fontsize{30}{38}\selectfont Asia-Pacific} &
    {\fontsize{34}{42}\selectfont\bfseries 26} \\
    \rowcolor{white}
    {\fontsize{30}{38}\selectfont Middle East \& Africa} &
    {\fontsize{34}{42}\selectfont\bfseries 4} \\
    \rowcolor{accent!12}
    {\fontsize{30}{38}\selectfont Latin America} &
    {\fontsize{34}{42}\selectfont\bfseries 2} \\
  \end{tabular}

  \vspace{10pt}
  \colorbox{accent!18}{\parbox{0.92\linewidth}{\vspace{5pt}\centering
    {\fontsize{26}{32}\selectfont\color{textdark} Europe leads with 38 institutions; Asia-Pacific shows strongest upward trajectory}
  \vspace{5pt}}}
}

% ══════════════════════════════════════════════════════════
% KEY TRENDS — bottom center+right, span 2
% ══════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Key Trends for 2026}
]{name=trends, column=2, span=2, between=row15 and row20}{
  \fontsize{32}{44}\selectfont

  \vspace{4pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\vspace{8pt}
    \hspace{8pt}{\fontsize{34}{42}\selectfont\bfseries\color{secondary} Asian Universities Rising}\\[4pt]
    \hspace{8pt}{\fontsize{30}{38}\selectfont Chinese and South Korean institutions climb $\Rightarrow$ sustained research investment and international collaboration}
  \vspace{8pt}}}

  \vspace{10pt}

  \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{8pt}
    \hspace{8pt}{\fontsize{34}{42}\selectfont\bfseries\color{accent} UK Strength Persists}\\[4pt]
    \hspace{8pt}{\fontsize{30}{38}\selectfont 4 universities in Top 10 and 17 in Top 100 $\Rightarrow$ second most represented country globally}
  \vspace{8pt}}}

  \vspace{10pt}

  \colorbox{primary!18}{\parbox{0.94\linewidth}{\vspace{8pt}
    \hspace{8pt}{\fontsize{34}{42}\selectfont\bfseries\color{primary} Sustainability \& Employability Focus}\\[4pt]
    \hspace{8pt}{\fontsize{30}{38}\selectfont QS expands supplementary rankings with sustainability metrics and employer outcomes}
  \vspace{8pt}}}

  \vspace{10pt}

  \colorbox{secondary!14}{\parbox{0.94\linewidth}{\vspace{8pt}
    \hspace{8pt}{\fontsize{34}{42}\selectfont\bfseries\color{secondary} Most Comprehensive Edition}\\[4pt]
    \hspace{8pt}{\fontsize{30}{38}\selectfont 1,500+ institutions across 105 countries $\Rightarrow$ broadest evaluation scope to date}
  \vspace{8pt}}}
}

% ══════════════════════════════════════════════════════════
% FOOTER
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=4pt, bottom=4pt,
  halign=center, valign=center,
]{name=footer, column=1, span=3, between=row20 and bottom}{
  {\fontsize{26}{32}\selectfont Source: QS World University Rankings 2026 \quad|\quad topuniversities.com \quad|\quad Data as of 2026}
}

\end{tcbposter}
\end{document}

