\definecolor{accent}{HTML}{0D7377}
\definecolor{bgposter}{HTML}{F0F2F5}
\definecolor{textdark}{HTML}{1A1A2E}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8EDF5}
\definecolor{goldlight}{HTML}{FDF8EE}
\definecolor{teallight}{HTML}{EBF5F5}
