\definecolor{golddark}{HTML}{9A6E00}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
