  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldlight,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=goldtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=teallight,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=tealtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navylight,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
